import { groupTrend, categoryBreakdown, overlapAnalysis } from './analytics.mjs?v=20261106.1';
import { compact, money, range } from './utilities.mjs?v=20261106.1';

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct = n => new Intl.NumberFormat('en-SG',{style:'percent',maximumFractionDigits:1}).format(n);
const monthName = value => new Date(value+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'short',year:'numeric',timeZone:'UTC'});
const number = value => new Intl.NumberFormat('en-SG',{maximumFractionDigits:0}).format(value);
const colors = ['#8057ff','#88f9c0','#b3a0ff','#d4b2ff','#5bca9a','#9873ff','#c2fadd','#6e56c9','#a9b4f5','#b8dac9'];

export function dashboard(s, rows, context) {
  const {filters,trendRows,previousRows,comparisonRows,units,scenarioRate} = context;
  const previous = previousRows.reduce((a,r)=>a+r.amount,0);
  const change = previous > 0 ? (s.total-previous)/previous : null;
  const LBUs=s.activeUnitCount;
  const continents = new Set(s.unitStats.map(u=>u.continent).filter(c=>c&&c!=='Unspecified'));
  const eligible=s.opportunities.reduce((a,v)=>a+v.eligibleSpend,0);
  const categories=categoryBreakdown(rows);
  const top5 = s.vendorStats.slice(0,5).reduce((a,v)=>a+Math.max(0,v.total),0);
  return `<div class="dashboard-intro"><div class="dashboard-tabs"><span class="selected-tab">Singapore LBU overview</span><span class="dashboard-scope">${LBUs} ${LBUs===1?'LBU':'LBUs'} <span>·</span> Singapore</span></div><span class="data-stamp"><i></i>${context.demo?'SYNTHETIC DATA':'BROWSER-LOCAL DATA'} <span>/</span> SGD</span></div>
  <section class="stats-grid dashboard-stats" aria-label="Spend at a glance">
    <article class="stat-card"><div class="stat-top"><span>Net spend</span><span class="metric-icon">↗</span></div><div class="stat-value">${compact(s.total)}</div><div class="stat-bottom">${change!==null?`<span class="delta ${change<=0?'down':'up'}">${change>0?'↗':'↘'} ${pct(Math.abs(change))}</span><span>vs. same months last year</span>`:'<span>Net of credits · current scope</span>'}</div></article>
    <article class="stat-card"><div class="stat-top"><span>Shared-supplier spend</span><span class="metric-icon">⋈</span></div><div class="stat-value">${compact(s.sharedSpend)}</div><div class="stat-bottom"><span class="mint">${pct(s.total>0?s.sharedSpend/s.total:0)}</span><span>of net spend in scope</span></div><div class="metric-track"><span style="width:${Math.min(100,Math.max(0,s.total>0?s.sharedSpend/s.total*100:0))}%"></span></div></article>
    <article class="stat-card"><div class="stat-top"><span>Supplier base</span><span class="metric-icon">◎</span></div><div class="stat-value">${number(s.vendorCount)}<span class="metric-unit">${s.vendorCount===1?'supplier':'suppliers'}</span></div><div class="stat-bottom"><span class="lavender">${s.sharedCount} shared</span><span>across 2+ LBUs</span></div><div class="supplier-dots" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i class="${i<s.sharedCount?'lit':''}"></i>`).join('')}</div></article>
    <article class="stat-card featured"><div class="stat-top"><span>Illustrative savings potential</span><span class="metric-icon">✧</span></div><div class="stat-value range">${s.estimatedHigh?range(s.estimatedLow,s.estimatedHigh):'S$0'}</div><div class="stat-bottom"><span>${s.opportunities.length} distinct sourcing ${s.opportunities.length===1?'opportunity':'opportunities'}</span></div><button class="metric-link" data-view="opportunities">Explore opportunities <span>↗</span></button></article>
  </section>
  <div class="analytics-primary-grid">${trendPanel(trendRows,comparisonRows,context)}${lbuPanel(s,context)}</div>
  <div class="analytics-secondary-grid">${categoryPanel(categories,s,filters)}${supplierPanel(s,top5)}${scenarioPanel(eligible,scenarioRate)}</div>
  ${connectionPanel(s,rows,context)}
  <section class="country-strip"><div class="section-title-row"><div><h2>Your Singapore LBU portfolio</h2><p>Select an LBU to focus the entire dashboard.</p></div><button class="text-button" data-view="units">Compare LBUs ↗</button></div><div class="country-tile-grid lbu-tile-grid">${units.map(u=>{const stat=s.unitStats.find(x=>x.id===u.id);return `<button class="country-tile ${filters.unit===u.id?'selected':''} ${!stat?'out-of-scope':''}" data-focus-unit="${esc(u.id)}" aria-pressed="${filters.unit===u.id}"><div class="country-tile-top"><span class="country-code">${esc(u.code)}</span><span class="country-direction">↗</span></div><strong>${esc(u.name)}</strong><small>Singapore · ${stat?.vendorCount||0} suppliers</small><span class="country-total">${stat?compact(stat.total):'—'}</span></button>`;}).join('')}</div></section>`;
}

function trendPanel(rows, comparisonRows, context) {
  let points=groupTrend(rows), previous=groupTrend(comparisonRows);
  const {filters,trendMode,compareEnabled}=context;
  const previousByMonth=new Map(previous.map(p=>[p.month.slice(5),p.total]));
  let currentRunning=0,previousRunning=0;
  const plotted=points.map(p=>{
    const prev=previousByMonth.get(p.month.slice(5))||0;
    currentRunning+=p.total;previousRunning+=prev;
    return {...p,value:trendMode==='cumulative'?currentRunning:p.total,previous:trendMode==='cumulative'?previousRunning:prev};
  });
  const w=640,h=215,left=52,right=20,top=22,bottom=29;
  const values=plotted.flatMap(p=>compareEnabled?[p.value,p.previous]:[p.value]);
  const max=Math.max(100,...values), min=Math.min(0,...values);
  const y=v=>top+(max-v)/(max-min)*(h-top-bottom);
  const x=i=>left+(plotted.length>1?i/(plotted.length-1):.5)*(w-left-right);
  const path=field=>plotted.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p[field]).toFixed(1)}`).join(' ');
  const area=plotted.length?`${path('value')} L${x(plotted.length-1)},${y(0)} L${x(0)},${y(0)} Z`:'';
  const total=rows.reduce((a,r)=>a+r.amount,0);
  const hasPrevious=compareEnabled&&comparisonRows.length>0;
  return `<section class="panel trend-panel" aria-label="Monthly spend explorer"><div class="panel-header"><div><h2>Spend over time <span class="heading-dot"></span></h2><p class="panel-subtitle">${trendMode==='cumulative'?'Cumulative':'Monthly'} net spend · full reporting period</p></div><div class="segmented-control" aria-label="Trend display"><button data-trend="monthly" aria-pressed="${trendMode==='monthly'}" class="${trendMode==='monthly'?'active':''}">Monthly</button><button data-trend="cumulative" aria-pressed="${trendMode==='cumulative'}" class="${trendMode==='cumulative'?'active':''}">Cumulative</button></div></div><div class="trend-summary"><strong>${compact(total)}</strong><div class="chart-legend"><span><i class="legend-line"></i>${filters.period==='all'?'Selected periods':esc(filters.period)}</span><button id="compare-toggle" aria-pressed="${compareEnabled&&filters.period!=='all'}" ${filters.period==='all'?'disabled':''} title="Toggle same-month prior year comparison"><i class="legend-line mint-line ${compareEnabled?'':'muted-line'}"></i>Prior year ${compareEnabled&&filters.period!=='all'?'✓':'+'}</button></div></div>${plotted.length?`<div class="trend-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(trendMode)} spend by month; use the month buttons below to filter"><defs><linearGradient id="trend-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6331fb" stop-opacity=".38"/><stop offset="1" stop-color="#6331fb" stop-opacity="0"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const v=min+(max-min)*(i/3);return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" class="chart-gridline"/><text x="${left-9}" y="${y(v)+3}" text-anchor="end" class="axis-label">${compact(v).replace('S$','')}</text>`;}).join('')}<path d="${area}" fill="url(#trend-fill)"/>${hasPrevious?`<path d="${path('previous')}" class="comparison-line"/>`:''}<path d="${path('value')}" class="spend-line"/>${plotted.map((p,i)=>`<g class="chart-point ${filters.month===p.month?'selected':''}"><line x1="${x(i)}" x2="${x(i)}" y1="${top}" y2="${h-bottom}"/><circle cx="${x(i)}" cy="${y(p.value)}" r="${filters.month===p.month?5:3.5}"/><title>${monthName(p.month)}: ${money(p.value)}${hasPrevious?`; prior year ${money(p.previous)}`:''}</title></g>`).join('')}</svg><div class="month-buttons" style="--months:${plotted.length}">${plotted.map(p=>`<button data-month="${p.month}" aria-pressed="${filters.month===p.month}" class="${filters.month===p.month?'active':''}" title="${monthName(p.month)} · ${money(p.total)}">${monthName(p.month).split(' ')[0]}${filters.period==='all'?`<small>${p.month.slice(2,4)}</small>`:''}</button>`).join('')}</div></div>`:'<div class="chart-empty">No spend in this reporting scope.</div>'}<div class="chart-footnote"><span><span class="tiny-cross">⌖</span> Click a month to focus all analysis</span><span>${hasPrevious?'Prior year aligned to the same months':filters.period==='all'?'Comparison disabled across multiple years':'No prior-year comparison in scope'}</span></div></section>`;
}

function lbuPanel(s,context) {
  const {units,filters}=context;
  const max=Math.max(1,...s.unitStats.map(u=>u.total));
  const allShared=units.length>=2?s.vendorStats.filter(v=>v.unitCount===units.length).length:0;
  return `<section class="panel lbu-panel" aria-label="Singapore LBU spend comparison"><div class="panel-header"><div><h2>One Singapore. Connected LBUs.</h2><p class="panel-subtitle">Your market is shared. So is your buying power.</p></div><span class="market-badge">SG <i></i></span></div><div class="lbu-network"><svg viewBox="0 0 420 90" aria-hidden="true"><defs><linearGradient id="lbu-bridge"><stop stop-color="#8057ff"/><stop offset="1" stop-color="#88f9c0"/></linearGradient></defs><path d="M58 72Q210 -35 362 72M58 72Q140 25 210 72M210 72Q290 25 362 72" fill="none" stroke="url(#lbu-bridge)" stroke-width="1.5"/><text x="210" y="28" text-anchor="middle">SINGAPORE</text><circle cx="58" cy="72" r="5" fill="#8057ff"/><circle cx="210" cy="72" r="5" fill="#88f9c0"/><circle cx="362" cy="72" r="5" fill="#b3a0ff"/></svg><div class="lbu-node-labels">${units.map(u=>`<span>${esc(u.name)}</span>`).join('')}</div></div><div class="lbu-comparison-rows">${units.map(u=>{const stat=s.unitStats.find(x=>x.id===u.id),total=stat?.total||0;return `<button class="lbu-comparison-row ${filters.unit===u.id?'selected':''}" data-focus-unit="${esc(u.id)}" aria-pressed="${filters.unit===u.id}"><span class="lbu-dot" style="background:${u.color||'#8057ff'}"></span><span class="lbu-row-name">${esc(u.name)}<small>${stat?.vendorCount||0} suppliers</small></span><strong>${stat?compact(total):'—'}</strong><span class="lbu-mini-bar"><i style="width:${Math.max(0,total/max*100)}%;background:${u.color||'#8057ff'}"></i></span><span class="supplier-arrow">↗</span></button>`;}).join('')}</div><div class="lbu-panel-foot"><span><strong>${allShared}</strong> suppliers used by all ${units.length} LBUs</span><button class="text-button" data-view="overlap">See overlap ↗</button></div></section>`;
}

function connectionPanel(s,rows,context) {
  const {units}=context, analysis=overlapAnalysis(rows,units,s.vendorStats);
  const shared=s.vendorStats.filter(v=>v.unitCount>=2).slice(0,5);
  return `<div class="connection-grid"><section class="panel overlap-preview"><div class="panel-header"><div><h2>The overlap, side by side.</h2><p class="panel-subtitle">Largest shared suppliers · net spend by LBU</p></div><button class="text-button" data-view="overlap">Full matrix ↗</button></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th scope="col">Supplier</th>${units.map(u=>`<th scope="col">${esc(u.name)}</th>`).join('')}</tr></thead><tbody>${shared.map(v=>`<tr><td><button class="row-link" data-vendor="${esc(v.id)}">${esc(v.name)}</button><span class="row-sub">${v.unitCount} LBUs</span></td>${units.map(u=>`<td class="amount ${v.byUnit[u.id]>0?'overlap-amount':''}">${v.byUnit[u.id]?compact(v.byUnit[u.id]):'—'}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${units.length+1}">No shared suppliers in this selection. Select all LBUs to compare.</td></tr>`}</tbody></table></div></section><section class="panel category-signal-teaser"><div class="panel-header"><div><span class="eyebrow">LOOK BEYOND THE VENDOR</span><h2>Same need. Different suppliers?</h2></div><span class="scenario-star">⋈</span></div><div class="category-teaser-body"><strong>${analysis.fragmentedCount}<span>category signals</span></strong><p>Find LBUs buying the same category through different supplier panels. Compare scope before combining demand.</p><div class="signal-chips">${analysis.categories.filter(c=>c.fragmented).slice(0,3).map(c=>`<button data-category-focus="${esc(c.name)}">${esc(c.name)} ↗</button>`).join('')}</div><button class="button button-mint wide-button" data-view="categories">Compare category choices ↗</button><small>Review signals · no additional savings estimate</small></div></section></div>`;
}

function categoryPanel(categories,s,filters) {
  const max=Math.max(1,...categories.map(c=>c.total));
  return `<section class="panel category-panel"><div class="panel-header"><div><h2>Category mix</h2><p class="panel-subtitle">${categories.length>6?'Largest 6 of '+categories.length+' categories':'What your portfolio buys'}</p></div><span class="pill">${categories.length} categories</span></div><div class="category-bars">${categories.slice(0,6).map((c,i)=>`<button class="category-row ${filters.category===c.name?'active':''}" data-category="${esc(c.name)}" aria-pressed="${filters.category===c.name}"><span class="category-row-top"><span>${esc(c.name)}</span><strong>${compact(c.total)}</strong></span><span class="category-bar-track"><i style="width:${Math.max(0,c.total/max*100)}%;background:${colors[i%colors.length]}"></i></span><span class="category-percent">${pct(s.total>0?c.total/s.total:0)} of scoped spend</span></button>`).join('')||'<p class="panel-subtitle">No categories in scope.</p>'}</div><div class="panel-bottom-note">Select a category to focus your portfolio ↗</div></section>`;
}

function supplierPanel(s,top5) {
  const concentration=s.positiveSpend>0?top5/s.positiveSpend:0;
  const r=43,c=2*Math.PI*r;
  return `<section class="panel supplier-panel"><div class="panel-header"><div><h2>Supplier concentration</h2><p class="panel-subtitle">Where your buying power sits</p></div><button class="text-button" data-view="overlap" aria-label="Explore all suppliers">↗</button></div><div class="concentration-summary"><svg viewBox="0 0 110 110" role="img" aria-label="Top five suppliers ${pct(concentration)} of positive supplier spend"><circle cx="55" cy="55" r="${r}" class="donut-track"/><circle cx="55" cy="55" r="${r}" class="donut-value" stroke-dasharray="${concentration*c} ${c}" transform="rotate(-90 55 55)"/><text x="55" y="53" text-anchor="middle" class="donut-text">${pct(concentration)}</text><text x="55" y="68" text-anchor="middle" class="donut-subtext">TOP FIVE</text></svg><div><strong>${compact(top5)}</strong><span>with your five largest suppliers</span><small>Share of positive net supplier spend</small></div></div><div class="top-supplier-list">${s.vendorStats.slice(0,5).map((v,i)=>`<button data-vendor="${esc(v.id)}"><span class="supplier-rank">0${i+1}</span><span>${esc(v.name)}<small>${v.unitCount} ${v.unitCount===1?'LBU':'LBUs'}</small></span><strong>${compact(v.total)}</strong><span class="supplier-arrow">↗</span></button>`).join('')||'<p class="panel-subtitle">No suppliers in scope.</p>'}</div></section>`;
}

function scenarioPanel(eligible,rate) {
  return `<section class="panel scenario-panel"><div class="panel-header"><div><span class="eyebrow">WHAT IF EXPLORER</span><h2>Put your scale to work.</h2><p class="panel-subtitle">Model a coordinated buying scenario.</p></div><span class="scenario-star">✧</span></div><div class="scenario-body"><div class="scenario-equation"><span>Assumed improvement</span><output id="scenario-rate-output" for="scenario-rate">${rate}%</output></div><input id="scenario-rate" type="range" min="1" max="12" step=".5" value="${rate}" aria-label="Assumed improvement rate" style="--progress:${(rate-1)/11*100}%"><div class="range-bounds"><span>1%</span><span>12%</span></div><div class="scenario-result"><small>Illustrative potential</small><strong id="scenario-result" aria-live="polite">${compact(Math.round(eligible*rate/100))}</strong><span>on ${compact(eligible)} eligible shared-supplier spend</span></div><p>One adjustable assumption across distinct supplier opportunities. This scenario is separate from the vendor-specific estimate above.</p><button class="button button-mint wide-button" data-view="opportunities">Explore the sourcing moves <span>↗</span></button><small class="scenario-disclaimer">Scenario estimate · not a committed or realized saving</small></div></section>`;
}
